window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"sl-40001","module":"shuliang","prompt":"把330个名额按9:8:5的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["195","75","255","135"],"answer":3,"explanation":"总份数=9+8+5=22，每份330÷22=15个，最多的班级分得9×15=135个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40002","module":"shuliang","prompt":"一个长方体的长、宽、高分别为10厘米、6厘米、8厘米，它的体积是多少立方厘米？","options":["60","376","24","480"],"answer":3,"explanation":"长方体体积=长×宽×高=10×6×8=480立方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40003","module":"shuliang","prompt":"已知等差数列的前10项和为255，前20项和为1010，则该数列的公差是多少？","options":["6","5","4","1"],"answer":1,"explanation":"S20−2×S10=(1010)−2×(255)=500=100d（第11到20项之和比前10项之和多100d），故d=5。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40004","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才13岁。”乙对甲说：“当我到你这么大时，你就25岁了。”甲今年多少岁？","options":["17","21","23","19"],"answer":1,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙13岁，即乙现在为x+d；乙到甲现在这么大时甲25岁，即甲现在为y−d。由y−d−(x+d)=d得d=(25−13)÷3=4，甲今年=25−4=21岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40005","module":"shuliang","prompt":"一个长方体的长、宽、高分别为5厘米、10厘米、9厘米，它的表面积是多少平方厘米？","options":["48","450","24","370"],"answer":3,"explanation":"长方体表面积=2×（长×宽+宽×高+长×高）=2×(50+90+45)=370平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40006","module":"shuliang","prompt":"甲数与乙数之比为2:2，乙数与丙数之比为2:5。甲数是丙数的多少倍？","options":["5/2","2/5","1/2","4/7"],"answer":1,"explanation":"甲:丙=2×2:2×5=4:10，甲是丙的2/5倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40007","module":"shuliang","prompt":"5名选手排成一排合影留念，其中甲、乙两人必须相邻，共有多少种不同的排法？","options":["96","120","24","48"],"answer":3,"explanation":"把甲、乙捆绑成一个整体，与其余3人共4个元素全排列，有(4)!=24种；甲、乙内部可交换有2种；共2×24=48种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40008","module":"shuliang","prompt":"把144个名额按4:6:2的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["120","24","72","73"],"answer":2,"explanation":"总份数=4+6+2=12，每份144÷12=12个，最多的班级分得6×12=72个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40009","module":"shuliang","prompt":"一个长方形的长为15米，宽为8米，它的周长是多少米？","options":["120","46","23","48"],"answer":1,"explanation":"长方形周长=2×（长+宽）=2×(15+8)=46米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40011","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行60千米，按原路返回时每小时行40千米。该车往返全程的平均速度是多少千米/小时？","options":["50","48","47","60"],"answer":1,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/60+1/40)=2×60×40÷(60+40)=48千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40012","module":"shuliang","prompt":"某单位组织61人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["800","769","618","680"],"answer":3,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为680元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40013","module":"shuliang","prompt":"一项工程，师傅甲先做16天、师傅乙再做14天恰好完成；若师傅乙先做16天、师傅甲再做14天也恰好完成。两人合作，需要多少天完成？","options":["15","30","2","16"],"answer":0,"explanation":"设师傅甲每天完成x、师傅乙每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=30÷2=15天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40014","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油11升；乙种卡车每次可运3吨货物，耗油7升。现要运送48吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["88","92","82","112"],"answer":0,"explanation":"甲车每吨耗油11/6升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：8车次运48吨，余0吨用乙车0次，共耗油88升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40015","module":"shuliang","prompt":"张三、李四两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地30千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地66千米处。问A、B两地相距多少千米？","options":["90","105","58","78"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且张三行30千米，故第二次相遇时张三共行90千米。90大于一个全程而小于两个全程，说明张三已从B地折返，其位置距A地为2S−90（S为全程）。由2S−90=66，解得S=78千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40016","module":"shuliang","prompt":"今年父子二人年龄之和是110岁，父亲年龄是儿子年龄的4倍。父亲今年多少岁？","options":["88","22","90","86"],"answer":0,"explanation":"儿子年龄为1份，父亲为4份，共5份；儿子=110÷5=22岁，父亲=4×22=88岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40017","module":"shuliang","prompt":"轿车、面包车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地56千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地72千米处。问A、B两地相距多少千米？","options":["110","138","120","168"],"answer":2,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且轿车行56千米，故第二次相遇时轿车共行168千米。168大于一个全程而小于两个全程，说明轿车已从B地折返，其位置距A地为2S−168（S为全程）。由2S−168=72，解得S=120千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40018","module":"shuliang","prompt":"一项工程，老周单独做需要15天完成，老吴单独做需要24天完成。现两人合作5天后，剩余部分由老吴单独完成，还需要多少天？","options":["11","19","14","24"],"answer":0,"explanation":"两人每天合作完成1/15+1/24=(15+24)/360，5天完成195/360，剩165/360；老吴每天完成1/24，还需24×165/360=11天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40019","module":"shuliang","prompt":"一项工程，张师傅先做14天、李师傅再做6天恰好完成；若李师傅先做14天、张师傅再做6天也恰好完成。两人合作，需要多少天完成？","options":["8","20","10","11"],"answer":2,"explanation":"设张师傅每天完成x、李师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=20÷2=10天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40020","module":"shuliang","prompt":"某商场促销“满200减20”，小明购买了标价800元的商品（满足优惠条件）。实际付款相当于打几折？","options":["8折","10折","9折","1折"],"answer":2,"explanation":"优惠后实付800−4×20=720元，720÷800=9/10，相当于打9折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40021","module":"shuliang","prompt":"某商品进价600元，售价1140元。该商品的利润率是多少？","options":["90%","92%","81%","180%"],"answer":0,"explanation":"利润=1140−600=540元，利润率=540÷600×100%=90%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40022","module":"shuliang","prompt":"甲数是乙数的3倍，两数之和是112。乙数是多少？","options":["84","28","31","26"],"answer":1,"explanation":"乙数为1份，甲数为3份，共4份；乙数=112÷4=28。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40023","module":"shuliang","prompt":"把264个名额按9:6:9的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["66","99","165","100"],"answer":1,"explanation":"总份数=9+6+9=24，每份264÷24=11个，最多的班级分得9×11=99个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40024","module":"shuliang","prompt":"已知等差数列的前10项和为240，前20项和为880，则该数列的公差是多少？","options":["5","4","3","1"],"answer":1,"explanation":"S20−2×S10=(880)−2×(240)=400=100d（第11到20项之和比前10项之和多100d），故d=4。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40025","module":"shuliang","prompt":"某商品按定价出售每件可赚20元，若按定价的8折出售，每件将亏损40元。该商品的进价是多少元？","options":["60","304","262","280"],"answer":3,"explanation":"设进价为C，定价为C+20；8折售价为8/10×(C+20)=C−40，解得C=280元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40026","module":"shuliang","prompt":"袋中有5个红球和3个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["3/8","5/8","1","1/2"],"answer":1,"explanation":"共有8个球，红球5个，取到红球的概率为5/8。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40027","module":"shuliang","prompt":"某商品进价每件50元，售价每件90元时每天可卖84件。售价每提高1元，每天少卖3件。要使每天利润最大，售价应定为每件多少元？","options":["85","84","83","90"],"answer":1,"explanation":"设售价提高k元，每天利润=(40+k)×(84−3k)，是关于k的二次函数，当k=-6时最大，此时售价=90+-6=84元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40028","module":"shuliang","prompt":"已知等差数列的前10项和为130，前20项和为460，则该数列的公差是多少？","options":["33","3","1","2"],"answer":3,"explanation":"S20−2×S10=(460)−2×(130)=200=100d（第11到20项之和比前10项之和多100d），故d=2。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40029","module":"shuliang","prompt":"快车、慢车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地25千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地69千米处。问A、B两地相距多少千米？","options":["88","72","60","75"],"answer":1,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且快车行25千米，故第二次相遇时快车共行75千米。75大于一个全程而小于两个全程，说明快车已从B地折返，其位置距A地为2S−75（S为全程）。由2S−75=69，解得S=72千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40030","module":"shuliang","prompt":"某商品按定价出售每件可赚80元，若按定价的9折出售，每件将亏损10元。该商品的进价是多少元？","options":["90","850","804","820"],"answer":3,"explanation":"设进价为C，定价为C+80；9折售价为9/10×(C+80)=C−10，解得C=820元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40031","module":"shuliang","prompt":"今天是星期日，再过169天是星期几？","options":["星期一","星期二","星期日","星期三"],"answer":0,"explanation":"169÷7=24余1，星期日往后推1天是星期一。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40032","module":"shuliang","prompt":"某小组共有8名成员，现从中随机选出4名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["70","55","15","59"],"answer":1,"explanation":"从8人中选4人共C(8,4)=70种；甲、乙都不入选有C(6,4)=15种；故至少一人入选共70−15=55种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40033","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才9岁。”乙对甲说：“当我到你这么大时，你就36岁了。”甲今年多少岁？","options":["28","18","27","25"],"answer":2,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙9岁，即乙现在为x+d；乙到甲现在这么大时甲36岁，即甲现在为y−d。由y−d−(x+d)=d得d=(36−9)÷3=9，甲今年=36−9=27岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40034","module":"shuliang","prompt":"同时掷两枚均匀的骰子，点数之和为6的概率是多少？","options":["1/12","1/9","1/6","5/36"],"answer":3,"explanation":"两枚骰子共6×6=36种等可能结果，点数之和为6的有5种，概率为5/36。","exam":"通用基础","__sub":"概率问题","diff":2},{"id":"sl-40035","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才11岁。”乙对甲说：“当我到你这么大时，你就20岁了。”甲今年多少岁？","options":["18","14","17","15"],"answer":2,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙11岁，即乙现在为x+d；乙到甲现在这么大时甲20岁，即甲现在为y−d。由y−d−(x+d)=d得d=(20−11)÷3=3，甲今年=20−3=17岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40036","module":"shuliang","prompt":"已知等差数列的前10项和为195，前20项和为690，则该数列的公差是多少？","options":["3","4","2","1"],"answer":0,"explanation":"S20−2×S10=(690)−2×(195)=300=100d（第11到20项之和比前10项之和多100d），故d=3。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40037","module":"shuliang","prompt":"某商品进价400元，售价444元。该商品的利润率是多少？","options":["11%","13%","10%","22%"],"answer":0,"explanation":"利润=444−400=44元，利润率=44÷400×100%=11%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40038","module":"shuliang","prompt":"5个正整数之和为41（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["39","41","37","36"],"answer":2,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=41−4×1=37。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40039","module":"shuliang","prompt":"6个正整数之和为49（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["9","12","8","11"],"answer":0,"explanation":"最大数最小时各数尽量平均，49÷6=8余1，故最大数至少为9（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40040","module":"shuliang","prompt":"某商品按定价出售每件可赚80元，若按定价的8折出售，每件将亏损30元。该商品的进价是多少元？","options":["470","501","442","110"],"answer":0,"explanation":"设进价为C，定价为C+80；8折售价为8/10×(C+80)=C−30，解得C=470元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40041","module":"shuliang","prompt":"两个正数的和为14，要使它们的乘积最大，则最大的乘积是多少？","options":["14","49","52","46"],"answer":1,"explanation":"两数和一定时，两数相等时乘积最大，均为14÷2=7，最大乘积=7×7=49。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40042","module":"shuliang","prompt":"5个正整数之和为54（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["54","50","53","49"],"answer":1,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=54−4×1=50。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40043","module":"shuliang","prompt":"张三和李四分别从相距336千米的两地同时出发，相向而行。张三每小时行59千米，李四每小时行53千米，经过多少小时两车相遇？","options":["5","3","2","4"],"answer":1,"explanation":"两车速度之和为59+53=112千米/小时，相遇时间=336÷112=3小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40044","module":"shuliang","prompt":"A接水需要6分钟，B接水需要2分钟，C接水需要9分钟，D接水需要3分钟，E接水需要7分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["27","69","60","36"],"answer":3,"explanation":"让用时短的人先接水可使总等待时间最短。按2、3、6、7、9的顺序，总等待=2×4+3×3+6×2+7×1+9×0=36分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40045","module":"shuliang","prompt":"今年父子二人年龄之和是88岁，父亲年龄是儿子年龄的3倍。父亲今年多少岁？","options":["22","66","70","64"],"answer":1,"explanation":"儿子年龄为1份，父亲为3份，共4份；儿子=88÷4=22岁，父亲=3×22=66岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40046","module":"shuliang","prompt":"4个正整数之和为47（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["48","47","44","43"],"answer":2,"explanation":"要使最大的数最大，其余3个数都取最小值1，故最大数=47−3×1=44。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40047","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需22小时，逆流需46小时，两码头相距506千米。该轮船在静水中的速度是多少千米/小时？","options":["23","6","17","15"],"answer":2,"explanation":"顺流速度=506÷22=23千米/小时，逆流速度=506÷46=11千米/小时；静水速度=(23+11)÷2=17千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40048","module":"shuliang","prompt":"某单位组织138人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["1600","1465","1309","1360"],"answer":3,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为1360元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40049","module":"shuliang","prompt":"某淘汰赛共有25支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["12","25","24","48"],"answer":2,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰24支，故共需24场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40050","module":"shuliang","prompt":"甲和乙分别从相距164千米的两地同时出发，相向而行。甲每小时行40千米，乙每小时行42千米，经过多少小时两车相遇？","options":["42","3","1","2"],"answer":3,"explanation":"两车速度之和为40+42=82千米/小时，相遇时间=164÷82=2小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40051","module":"shuliang","prompt":"快车、慢车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地51千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地63千米处。问A、B两地相距多少千米？","options":["153","128","97","108"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且快车行51千米，故第二次相遇时快车共行153千米。153大于一个全程而小于两个全程，说明快车已从B地折返，其位置距A地为2S−153（S为全程）。由2S−153=63，解得S=108千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40052","module":"shuliang","prompt":"某商品进价每件30元，售价每件70元时每天可卖162件。售价每提高1元，每天少卖3件。要使每天利润最大，售价应定为每件多少元？","options":["77","79","76","70"],"answer":0,"explanation":"设售价提高k元，每天利润=(40+k)×(162−3k)，是关于k的二次函数，当k=7时最大，此时售价=70+7=77元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40053","module":"shuliang","prompt":"一个长方体的长、宽、高分别为7厘米、5厘米、8厘米，它的表面积是多少平方厘米？","options":["262","280","20","40"],"answer":0,"explanation":"长方体表面积=2×（长×宽+宽×高+长×高）=2×(35+40+56)=262平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40054","module":"shuliang","prompt":"5个正整数之和为56（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["12","14","11","13"],"answer":0,"explanation":"最大数最小时各数尽量平均，56÷5=11余1，故最大数至少为12（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40055","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是24立方分米。圆锥的体积是多少立方分米？","options":["12","24","8","48"],"answer":2,"explanation":"等底等高的圆锥体积是圆柱的1/3，即24÷3=8立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40056","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有31人，参加羽毛球赛的有35人，参加乒乓球赛的有23人；同时参加篮球和羽毛球的有12人，参加篮球和乒乓球的有7人，参加羽毛球和乒乓球的有6人，三项都参加的有2人。只参加其中一项比赛的有多少人？","options":["47","45","44","66"],"answer":1,"explanation":"只参加篮球=31−12−7+2=14人；同理只参加羽毛球=19人，只参加乒乓球=12人；合计14+19+12=45人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40057","module":"shuliang","prompt":"某商品进价500元，售价800元。该商品的利润率是多少？","options":["120%","66%","51%","60%"],"answer":3,"explanation":"利润=800−500=300元，利润率=300÷500×100%=60%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40058","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才4岁。”乙对甲说：“当我到你这么大时，你就49岁了。”甲今年多少岁？","options":["32","19","37","34"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙4岁，即乙现在为x+d；乙到甲现在这么大时甲49岁，即甲现在为y−d。由y−d−(x+d)=d得d=(49−4)÷3=15，甲今年=49−15=34岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40059","module":"shuliang","prompt":"6个正整数之和为61（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["10","14","9","11"],"answer":3,"explanation":"最大数最小时各数尽量平均，61÷6=10余1，故最大数至少为11（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40060","module":"shuliang","prompt":"轿车、面包车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地45千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地21千米处。问A、B两地相距多少千米？","options":["135","93","63","78"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且轿车行45千米，故第二次相遇时轿车共行135千米。135大于一个全程而小于两个全程，说明轿车已从B地折返，其位置距A地为2S−135（S为全程）。由2S−135=21，解得S=78千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40061","module":"shuliang","prompt":"在一个边长为28厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["178","784","169","167"],"answer":2,"explanation":"正方形面积=784平方厘米，最大圆半径为14厘米，圆面积=3.14×14²=615平方厘米，剩余=784−615=169平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40062","module":"shuliang","prompt":"一项工程，甲单独做需要14天完成，乙单独做需要35天完成。两人（队）合作，需要多少天完成？","options":["25","49","21","10"],"answer":3,"explanation":"把工程总量看作1，两人效率之和为1/14+1/35=(14+35)/490，合作需要490÷(14+35)=10天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40063","module":"shuliang","prompt":"甲种卡车每次可运5吨货物，耗油9升；乙种卡车每次可运2吨货物，耗油8升。现要运送45吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["176","89","79","81"],"answer":3,"explanation":"甲车每吨耗油9/5升，乙车每吨耗油8/2升，甲车更省。尽量用甲车：9车次运45吨，余0吨用乙车0次，共耗油81升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40064","module":"shuliang","prompt":"一项工程，师傅甲单独做需要10天完成，师傅乙单独做需要15天完成。现两人合作4天后，剩余部分由师傅乙单独完成，还需要多少天？","options":["5","11","6","15"],"answer":0,"explanation":"两人每天合作完成1/10+1/15=(10+15)/150，4天完成100/150，剩50/150；师傅乙每天完成1/15，还需15×50/150=5天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40065","module":"shuliang","prompt":"甲数是乙数的5倍，两数之和是222。乙数是多少？","options":["33","185","44","37"],"answer":3,"explanation":"乙数为1份，甲数为5份，共6份；乙数=222÷6=37。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40066","module":"shuliang","prompt":"数列{aₙ}满足a₁=3，aₙ₊₁=2aₙ+1，则a7等于多少？","options":["253","260","255","256"],"answer":2,"explanation":"变形得aₙ₊₁+1=2(aₙ+1)，故aₙ+1=(3+1)×2^(n−1)，a7=(3+1)×64−1=255。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40067","module":"shuliang","prompt":"甲数与乙数之比为5:3，乙数与丙数之比为3:5。甲数是丙数的多少倍？","options":["16/15","1","2","3"],"answer":1,"explanation":"甲:丙=5×3:3×5=15:15，甲是丙的1倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40068","module":"shuliang","prompt":"两个数的和是108，差是28。这两个数中较大的数是多少？","options":["68","82","26","108"],"answer":0,"explanation":"小数=（和−差）÷2=40，大数=（和+差）÷2=68。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40069","module":"shuliang","prompt":"快车在慢车后方140千米处，两人同时同向出发。快车每小时行85千米，慢车每小时行50千米，经过多少小时快车追上慢车？","options":["4","5","6","140"],"answer":0,"explanation":"每小时快车比慢车多行85-50=35千米，追及时间=140÷35=4小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40070","module":"shuliang","prompt":"某商品进价每件20元，售价每件50元时每天可卖176件。售价每提高1元，每天少卖4件。要使每天利润最大，售价应定为每件多少元？","options":["50","58","56","57"],"answer":3,"explanation":"设售价提高k元，每天利润=(30+k)×(176−4k)，是关于k的二次函数，当k=7时最大，此时售价=50+7=57元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40071","module":"shuliang","prompt":"把266个名额按9:2:8的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["28","126","154","140"],"answer":1,"explanation":"总份数=9+2+8=19，每份266÷19=14个，最多的班级分得9×14=126个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40072","module":"shuliang","prompt":"甲数与乙数之比为3:3，乙数与丙数之比为3:2。甲数是丙数的多少倍？","options":["6/5","2/3","5/3","3/2"],"answer":3,"explanation":"甲:丙=3×3:3×2=9:6，甲是丙的3/2倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40073","module":"shuliang","prompt":"某商品进价900元，售价1188元。该商品的利润率是多少？","options":["26%","40%","32%","64%"],"answer":2,"explanation":"利润=1188−900=288元，利润率=288÷900×100%=32%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40074","module":"shuliang","prompt":"一项工程，一队单独做需要12天完成，二队单独做需要36天完成。两人（队）合作，需要多少天完成？","options":["24","48","9","12"],"answer":2,"explanation":"把工程总量看作1，两人效率之和为1/12+1/36=(12+36)/432，合作需要432÷(12+36)=9天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40075","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供12头牛吃24天，或供18头牛吃8天。若放33头牛，可以吃多少天？","options":["2","5","3","9"],"answer":2,"explanation":"每天长草量=(18×8−12×24)÷(8−24)=9份，原有草量=12×24−9×24=72份；33头牛每天净消耗33−9=24份，可吃72÷24=3天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40076","module":"shuliang","prompt":"甲数与乙数之比为4:5，乙数与丙数之比为5:2。甲数是丙数的多少倍？","options":["2","1/2","21/10","3"],"answer":0,"explanation":"甲:丙=4×5:5×2=20:10，甲是丙的2倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40077","module":"shuliang","prompt":"已知等差数列的前10项和为360，前20项和为1320，则该数列的公差是多少？","options":["5","7","6","1"],"answer":2,"explanation":"S20−2×S10=(1320)−2×(360)=600=100d（第11到20项之和比前10项之和多100d），故d=6。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40078","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才12岁。”乙对甲说：“当我到你这么大时，你就45岁了。”甲今年多少岁？","options":["33","23","36","34"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙12岁，即乙现在为x+d；乙到甲现在这么大时甲45岁，即甲现在为y−d。由y−d−(x+d)=d得d=(45−12)÷3=11，甲今年=45−11=34岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40079","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需18小时，逆流需50小时，两码头相距450千米。该轮船在静水中的速度是多少千米/小时？","options":["25","8","17","16"],"answer":2,"explanation":"顺流速度=450÷18=25千米/小时，逆流速度=450÷50=9千米/小时；静水速度=(25+9)÷2=17千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40080","module":"shuliang","prompt":"两个正数的和为26，要使它们的乘积最大，则最大的乘积是多少？","options":["168","26","173","169"],"answer":3,"explanation":"两数和一定时，两数相等时乘积最大，均为26÷2=13，最大乘积=13×13=169。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40081","module":"shuliang","prompt":"某班共有46人，参加数学竞赛的有17人，参加作文竞赛的有18人，参加英语竞赛的有21人；同时参加数学和作文的有6人，参加数学和英语的有6人，参加作文和英语的有8人，三项都参加的有3人。三项竞赛都不参加的有多少人？","options":["46","8","20","7"],"answer":3,"explanation":"至少参加一项的有17+18+21−6−6−8+3=39人，都不参加的有46−39=7人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40082","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有27人，参加羽毛球赛的有25人，参加乒乓球赛的有34人；同时参加篮球和羽毛球的有11人，参加篮球和乒乓球的有10人，参加羽毛球和乒乓球的有11人，三项都参加的有2人。只参加其中一项比赛的有多少人？","options":["29","28","25","56"],"answer":1,"explanation":"只参加篮球=27−11−10+2=8人；同理只参加羽毛球=5人，只参加乒乓球=15人；合计8+5+15=28人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40083","module":"shuliang","prompt":"两个数的和是118，差是8。这两个数中较大的数是多少？","options":["67","63","51","118"],"answer":1,"explanation":"小数=（和−差）÷2=55，大数=（和+差）÷2=63。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40084","module":"shuliang","prompt":"一个平底锅每次最多可以烙2张饼，每张饼两面都要烙，每面需要4分钟。烙6张饼最少需要多少分钟？","options":["25","48","24","22"],"answer":2,"explanation":"共需烙6×2=12面，每次最多烙2面，至少6锅次，最少6×4=24分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40085","module":"shuliang","prompt":"今年父子二人年龄之和是156岁，父亲年龄是儿子年龄的3倍。父亲今年多少岁？","options":["39","117","121","115"],"answer":1,"explanation":"儿子年龄为1份，父亲为3份，共4份；儿子=156÷4=39岁，父亲=3×39=117岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40086","module":"shuliang","prompt":"一个长方形的长为22米，宽为11米，它的面积是多少平方米？","options":["33","66","242","264"],"answer":2,"explanation":"长方形面积=长×宽=22×11=242平方米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40087","module":"shuliang","prompt":"已知等比数列的首项为4，公比为3，则它的第5项是多少？","options":["108","972","324","327"],"answer":2,"explanation":"等比数列第n项=首项×公比^(n−1)=4×3^(5-1)=324。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40088","module":"shuliang","prompt":"已知等差数列的首项为8，公差为4，则它的前14项之和是多少？","options":["482","840","476","468"],"answer":2,"explanation":"第14项=8+(14-1)×4=60，前14项和=n×(首项+末项)÷2=14×(8+60)÷2=476。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40089","module":"shuliang","prompt":"在一个边长为18厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["63","324","74","70"],"answer":3,"explanation":"正方形面积=324平方厘米，最大圆半径为9厘米，圆面积=3.14×9²=254平方厘米，剩余=324−254=70平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40090","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有31人，参加数学兴趣小组的有20人，两个小组都参加的有15人。两个小组至少参加一个的共有多少人？","options":["66","51","36","11"],"answer":2,"explanation":"都参加的15人被算了两次，需减去一次，故至少参加一个的人数=31+20−15=36人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40091","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有32人，参加物理组的有33人，参加化学组的有22人；同时参加数学和物理的有11人，参加数学和化学的有7人，参加物理和化学的有7人，三个组都参加的有5人。三个组至少参加一个的共有多少人？","options":["66","87","71","67"],"answer":3,"explanation":"由三集合容斥公式：至少参加一个=32+33+22−11−7−7+5=67人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40092","module":"shuliang","prompt":"轿车在面包车后方175千米处，两人同时同向出发。轿车每小时行88千米，面包车每小时行53千米，经过多少小时轿车追上面包车？","options":["5","6","7","175"],"answer":0,"explanation":"每小时轿车比面包车多行88-53=35千米，追及时间=175÷35=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40093","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有27人，参加羽毛球赛的有23人，参加乒乓球赛的有25人；同时参加篮球和羽毛球的有11人，参加篮球和乒乓球的有12人，参加羽毛球和乒乓球的有9人，三项都参加的有6人。只参加其中一项比赛的有多少人？","options":["29","31","27","49"],"answer":0,"explanation":"只参加篮球=27−11−12+6=10人；同理只参加羽毛球=9人，只参加乒乓球=10人；合计10+9+10=29人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40094","module":"shuliang","prompt":"张三、李四两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地57千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地63千米处。问A、B两地相距多少千米？","options":["117","142","105","171"],"answer":0,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且张三行57千米，故第二次相遇时张三共行171千米。171大于一个全程而小于两个全程，说明张三已从B地折返，其位置距A地为2S−171（S为全程）。由2S−171=63，解得S=117千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40095","module":"shuliang","prompt":"一项工程，一队先做4天、二队再做16天恰好完成；若二队先做4天、一队再做16天也恰好完成。两人合作，需要多少天完成？","options":["10","20","12","11"],"answer":0,"explanation":"设一队每天完成x、二队每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=20÷2=10天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40096","module":"shuliang","prompt":"5个正整数之和为32（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["32","28","30","27"],"answer":1,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=32−4×1=28。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40097","module":"shuliang","prompt":"袋中有6个红球和6个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1/2","1","1/4","1/3"],"answer":0,"explanation":"共有12个球，红球6个，取到红球的概率为6/12=1/2。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40098","module":"shuliang","prompt":"把96个名额按2:8:6的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["49","12","60","48"],"answer":3,"explanation":"总份数=2+8+6=16，每份96÷16=6个，最多的班级分得8×6=48个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40099","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油12升；乙种卡车每次可运2吨货物，耗油5升。现要运送66吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["132","134","130","165"],"answer":0,"explanation":"甲车每吨耗油12/6升，乙车每吨耗油5/2升，甲车更省。尽量用甲车：11车次运66吨，余0吨用乙车0次，共耗油132升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40100","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才16岁。”乙对甲说：“当我到你这么大时，你就55岁了。”甲今年多少岁？","options":["42","29","45","41"],"answer":0,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙16岁，即乙现在为x+d；乙到甲现在这么大时甲55岁，即甲现在为y−d。由y−d−(x+d)=d得d=(55−16)÷3=13，甲今年=55−13=42岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40101","module":"shuliang","prompt":"某商品按定价出售每件可赚70元，若按定价的9折出售，每件将亏损20元。该商品的进价是多少元？","options":["798","868","830","90"],"answer":2,"explanation":"设进价为C，定价为C+70；9折售价为9/10×(C+70)=C−20，解得C=830元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40102","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有20人，参加羽毛球赛的有32人，参加乒乓球赛的有34人；同时参加篮球和羽毛球的有10人，参加篮球和乒乓球的有8人，参加羽毛球和乒乓球的有12人，三项都参加的有3人。只参加其中一项比赛的有多少人？","options":["33","37","35","59"],"answer":2,"explanation":"只参加篮球=20−10−8+3=5人；同理只参加羽毛球=13人，只参加乒乓球=17人；合计5+13+17=35人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40103","module":"shuliang","prompt":"同一时刻，一根5米高的标杆在阳光下的影长为10米，附近一棵大树的影长为20米。这棵大树的高度是多少米？","options":["10","25","11","20"],"answer":0,"explanation":"同一时刻物高与影长成正比，树高=5×20÷10=10米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40104","module":"shuliang","prompt":"把57个名额按4:9:6的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["30","12","39","27"],"answer":3,"explanation":"总份数=4+9+6=19，每份57÷19=3个，最多的班级分得9×3=27个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40105","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有28人，参加羽毛球赛的有26人，参加乒乓球赛的有23人；同时参加篮球和羽毛球的有11人，参加篮球和乒乓球的有12人，参加羽毛球和乒乓球的有9人，三项都参加的有6人。只参加其中一项比赛的有多少人？","options":["31","33","27","51"],"answer":0,"explanation":"只参加篮球=28−11−12+6=11人；同理只参加羽毛球=12人，只参加乒乓球=8人；合计11+12+8=31人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40106","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有22人，参加羽毛球赛的有26人，参加乒乓球赛的有24人；同时参加篮球和羽毛球的有11人，参加篮球和乒乓球的有11人，参加羽毛球和乒乓球的有7人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["26","30","25","47"],"answer":0,"explanation":"只参加篮球=22−11−11+4=4人；同理只参加羽毛球=12人，只参加乒乓球=10人；合计4+12+10=26人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40107","module":"shuliang","prompt":"某商品按定价出售每件可赚50元，若按定价的9折出售，每件将亏损10元。该商品的进价是多少元？","options":["550","563","528","60"],"answer":0,"explanation":"设进价为C，定价为C+50；9折售价为9/10×(C+50)=C−10，解得C=550元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40108","module":"shuliang","prompt":"甲数是乙数的3倍，两数之和是136。乙数是多少？","options":["102","34","38","31"],"answer":1,"explanation":"乙数为1份，甲数为3份，共4份；乙数=136÷4=34。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40109","module":"shuliang","prompt":"今年甲的年龄是乙的5倍，11年后甲的年龄是乙的3倍。乙今年多少岁？","options":["11","13","10","121"],"answer":0,"explanation":"设乙今年x岁，则甲为5x岁；11年后：5x+11=3(x+11)，解得x=11岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40110","module":"shuliang","prompt":"某淘汰赛共有27支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["27","26","13","28"],"answer":1,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰26支，故共需26场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40111","module":"shuliang","prompt":"甲种卡车每次可运5吨货物，耗油9升；乙种卡车每次可运2吨货物，耗油6升。现要运送60吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["108","115","102","180"],"answer":0,"explanation":"甲车每吨耗油9/5升，乙车每吨耗油6/2升，甲车更省。尽量用甲车：12车次运60吨，余0吨用乙车0次，共耗油108升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40112","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供10头牛吃19天，或供23头牛吃6天。若放42头牛，可以吃多少天？","options":["3","5","2","4"],"answer":0,"explanation":"每天长草量=(23×6−10×19)÷(6−19)=4份，原有草量=10×19−4×19=114份；42头牛每天净消耗42−4=38份，可吃114÷38=3天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40113","module":"shuliang","prompt":"5个正整数之和为30（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["30","26","29","25"],"answer":1,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=30−4×1=26。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40114","module":"shuliang","prompt":"一项工程，王师傅先做4天、赵师傅再做18天恰好完成；若赵师傅先做4天、王师傅再做18天也恰好完成。两人合作，需要多少天完成？","options":["11","22","14","12"],"answer":0,"explanation":"设王师傅每天完成x、赵师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=22÷2=11天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40115","module":"shuliang","prompt":"6个正整数之和为46（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["8","10","7","9"],"answer":0,"explanation":"最大数最小时各数尽量平均，46÷6=7余4，故最大数至少为8（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40116","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才20岁。”乙对甲说：“当我到你这么大时，你就56岁了。”甲今年多少岁？","options":["32","44","47","43"],"answer":1,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙20岁，即乙现在为x+d；乙到甲现在这么大时甲56岁，即甲现在为y−d。由y−d−(x+d)=d得d=(56−20)÷3=12，甲今年=56−12=44岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40117","module":"shuliang","prompt":"已知等比数列的首项为4，公比为3，则它的第6项是多少？","options":["2916","972","324","975"],"answer":1,"explanation":"等比数列第n项=首项×公比^(n−1)=4×3^(6-1)=972。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40118","module":"shuliang","prompt":"客车、货车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地57千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地39千米处。问A、B两地相距多少千米？","options":["90","121","105","171"],"answer":2,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且客车行57千米，故第二次相遇时客车共行171千米。171大于一个全程而小于两个全程，说明客车已从B地折返，其位置距A地为2S−171（S为全程）。由2S−171=39，解得S=105千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40119","module":"shuliang","prompt":"快车、慢车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地71千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地27千米处。问A、B两地相距多少千米？","options":["213","130","96","120"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且快车行71千米，故第二次相遇时快车共行213千米。213大于一个全程而小于两个全程，说明快车已从B地折返，其位置距A地为2S−213（S为全程）。由2S−213=27，解得S=120千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40120","module":"shuliang","prompt":"4个正整数之和为61（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["15","18","16","17"],"answer":2,"explanation":"最大数最小时各数尽量平均，61÷4=15余1，故最大数至少为16（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40121","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有31人，参加羽毛球赛的有23人，参加乒乓球赛的有35人；同时参加篮球和羽毛球的有6人，参加篮球和乒乓球的有8人，参加羽毛球和乒乓球的有11人，三项都参加的有6人。只参加其中一项比赛的有多少人？","options":["57","61","55","70"],"answer":0,"explanation":"只参加篮球=31−6−8+6=23人；同理只参加羽毛球=12人，只参加乒乓球=22人；合计23+12+22=57人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40122","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是60立方分米。圆锥的体积是多少立方分米？","options":["60","20","30","120"],"answer":1,"explanation":"等底等高的圆锥体积是圆柱的1/3，即60÷3=20立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40123","module":"shuliang","prompt":"把180个名额按3:6:6的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["36","72","108","73"],"answer":1,"explanation":"总份数=3+6+6=15，每份180÷15=12个，最多的班级分得6×12=72个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40124","module":"shuliang","prompt":"甲接水需要10分钟，乙接水需要12分钟，丙接水需要3分钟，丁接水需要7分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["59","67","33","32"],"answer":2,"explanation":"让用时短的人先接水可使总等待时间最短。按3、7、10、12的顺序，总等待=3×3+7×2+10×1+12×0=33分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40125","module":"shuliang","prompt":"4个正整数之和为45（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["12","13","10","11"],"answer":0,"explanation":"最大数最小时各数尽量平均，45÷4=11余1，故最大数至少为12（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40126","module":"shuliang","prompt":"时钟5点50分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["125","133","119","55"],"answer":0,"explanation":"时针与12点方向夹角为30×5+0.5×50=175.0度，分针与12点方向夹角为6×50=300度，两针夹角为125度，取小于180度的角为125.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40127","module":"shuliang","prompt":"A接水需要9分钟，B接水需要6分钟，C接水需要7分钟，D接水需要10分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["81","41","70","32"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按6、7、9、10的顺序，总等待=6×3+7×2+9×1+10×0=41分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40128","module":"shuliang","prompt":"4个正整数之和为32（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["29","32","33","28"],"answer":0,"explanation":"要使最大的数最大，其余3个数都取最小值1，故最大数=32−3×1=29。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40129","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才15岁。”乙对甲说：“当我到你这么大时，你就51岁了。”甲今年多少岁？","options":["27","39","40","37"],"answer":1,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙15岁，即乙现在为x+d；乙到甲现在这么大时甲51岁，即甲现在为y−d。由y−d−(x+d)=d得d=(51−15)÷3=12，甲今年=51−12=39岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40130","module":"shuliang","prompt":"某单位组织71人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["800","834","555","680"],"answer":3,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为680元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40131","module":"shuliang","prompt":"一项工程，张师傅单独做需要12天完成，李师傅单独做需要36天完成。两人（队）合作，需要多少天完成？","options":["9","48","24","12"],"answer":0,"explanation":"把工程总量看作1，两人效率之和为1/12+1/36=(12+36)/432，合作需要432÷(12+36)=9天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40132","module":"shuliang","prompt":"一项工程，老周单独做需要28天完成，老吴单独做需要21天完成。两人（队）合作，需要多少天完成？","options":["12","49","7","25"],"answer":0,"explanation":"把工程总量看作1，两人效率之和为1/28+1/21=(28+21)/588，合作需要588÷(28+21)=12天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40133","module":"shuliang","prompt":"已知等差数列的前10项和为140，前20项和为480，则该数列的公差是多少？","options":["4","2","1","34"],"answer":1,"explanation":"S20−2×S10=(480)−2×(140)=200=100d（第11到20项之和比前10项之和多100d），故d=2。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40134","module":"shuliang","prompt":"今年父子二人年龄之和是124岁，父亲年龄是儿子年龄的3倍。父亲今年多少岁？","options":["31","93","98","88"],"answer":1,"explanation":"儿子年龄为1份，父亲为3份，共4份；儿子=124÷4=31岁，父亲=3×31=93岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40135","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行24千米，按原路返回时每小时行72千米。该车往返全程的平均速度是多少千米/小时？","options":["36","48","38","35"],"answer":0,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/24+1/72)=2×24×72÷(24+72)=36千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40136","module":"shuliang","prompt":"今年甲的年龄是乙的5倍，5年后甲的年龄是乙的4倍。乙今年多少岁？","options":["16","15","14","5"],"answer":1,"explanation":"设乙今年x岁，则甲为5x岁；5年后：5x+5=4(x+5)，解得x=15岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40137","module":"shuliang","prompt":"A接水需要11分钟，B接水需要12分钟，C接水需要7分钟，D接水需要9分钟，E接水需要3分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["102","107","62","42"],"answer":2,"explanation":"让用时短的人先接水可使总等待时间最短。按3、7、9、11、12的顺序，总等待=3×4+7×3+9×2+11×1+12×0=62分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40138","module":"shuliang","prompt":"4个正整数之和为60（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["19","17","13","15"],"answer":3,"explanation":"最大数最小时各数尽量平均，60÷4=15余0，故最大数至少为15（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40139","module":"shuliang","prompt":"袋中有3个红球和6个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1/3","2/3","1","1/2"],"answer":0,"explanation":"共有9个球，红球3个，取到红球的概率为3/9=1/3。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40140","module":"shuliang","prompt":"彩旗按“甲、乙、丙、丁、戊”的顺序循环排列，第24面彩旗是什么颜色？","options":["丁","戊","丙","甲"],"answer":0,"explanation":"周期为5，24÷5=4余4，第24面旗对应周期中的第4个，即“丁”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40141","module":"shuliang","prompt":"某单位组织77人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["840","961","679","800"],"answer":3,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为800元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40142","module":"shuliang","prompt":"6个正整数之和为35（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["5","7","6","9"],"answer":2,"explanation":"最大数最小时各数尽量平均，35÷6=5余5，故最大数至少为6（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40143","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需54小时，逆流需66小时，两码头相距1782千米。该轮船在静水中的速度是多少千米/小时？","options":["33","3","30","28"],"answer":2,"explanation":"顺流速度=1782÷54=33千米/小时，逆流速度=1782÷66=27千米/小时；静水速度=(33+27)÷2=30千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40144","module":"shuliang","prompt":"客车和货车的速度比为6:2，两人同时同地同向出发赛跑，当客车到达终点时，货车距终点还有20米。赛道全程是多少米？","options":["77","30","6","120"],"answer":1,"explanation":"同一时间内路程比等于速度比，货车走了全程的2/6，还差全程的4/6=20米，故全程=20×6÷4=30米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40145","module":"shuliang","prompt":"六本不同的书平均分成三组，每组两本，共有多少种不同的分法？","options":["30","15","5","45"],"answer":1,"explanation":"先按组选书：C(6,2)×C(4,2)×C(2,2)=15×6×1=90种；平均分组因组与组不排序需除以3!=6，共90÷6=15种。","exam":"通用基础","__sub":"排列组合","diff":3},{"id":"sl-40146","module":"shuliang","prompt":"今年父子二人年龄之和是90岁，父亲年龄是儿子年龄的2倍。父亲今年多少岁？","options":["64","30","60","58"],"answer":2,"explanation":"儿子年龄为1份，父亲为2份，共3份；儿子=90÷3=30岁，父亲=2×30=60岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40147","module":"shuliang","prompt":"一项工程，一队先做9天、二队再做11天恰好完成；若二队先做9天、一队再做11天也恰好完成。两人合作，需要多少天完成？","options":["20","10","2","11"],"answer":1,"explanation":"设一队每天完成x、二队每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=20÷2=10天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40148","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有21人，参加羽毛球赛的有24人，参加乒乓球赛的有23人；同时参加篮球和羽毛球的有10人，参加篮球和乒乓球的有8人，参加羽毛球和乒乓球的有11人，三项都参加的有6人。只参加其中一项比赛的有多少人？","options":["45","30","27","28"],"answer":3,"explanation":"只参加篮球=21−10−8+6=9人；同理只参加羽毛球=9人，只参加乒乓球=10人；合计9+9+10=28人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40149","module":"shuliang","prompt":"某商场促销“满100减20”，小明购买了标价400元的商品（满足优惠条件）。实际付款相当于打几折？","options":["2折","9折","7折","8折"],"answer":3,"explanation":"优惠后实付400−4×20=320元，320÷400=4/5，相当于打8折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40150","module":"shuliang","prompt":"已知等差数列的前10项和为290，前20项和为1180，则该数列的公差是多少？","options":["5","8","6","1"],"answer":2,"explanation":"S20−2×S10=(1180)−2×(290)=600=100d（第11到20项之和比前10项之和多100d），故d=6。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40151","module":"shuliang","prompt":"今天是星期三，再过47天是星期几？","options":["星期二","星期一","星期日","星期五"],"answer":1,"explanation":"47÷7=6余5，星期三往后推5天是星期一。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40152","module":"shuliang","prompt":"一项工程，师傅甲先做8天、师傅乙再做20天恰好完成；若师傅乙先做8天、师傅甲再做20天也恰好完成。两人合作，需要多少天完成？","options":["14","28","12","15"],"answer":0,"explanation":"设师傅甲每天完成x、师傅乙每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=28÷2=14天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40153","module":"shuliang","prompt":"甲数与乙数之比为2:4，乙数与丙数之比为4:5。甲数是丙数的多少倍？","options":["5/8","5/2","9/20","2/5"],"answer":3,"explanation":"甲:丙=2×4:4×5=8:20，甲是丙的2/5倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40154","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有41人，参加数学兴趣小组的有33人，两个小组都参加的有9人。两个小组至少参加一个的共有多少人？","options":["8","74","83","65"],"answer":3,"explanation":"都参加的9人被算了两次，需减去一次，故至少参加一个的人数=41+33−9=65人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40155","module":"shuliang","prompt":"一项工程，老周先做11天、老吴再做13天恰好完成；若老吴先做11天、老周再做13天也恰好完成。两人合作，需要多少天完成？","options":["12","24","2","13"],"answer":0,"explanation":"设老周每天完成x、老吴每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=24÷2=12天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40156","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有22人，参加物理组的有22人，参加化学组的有33人；同时参加数学和物理的有7人，参加数学和化学的有6人，参加物理和化学的有6人，三个组都参加的有5人。三个组至少参加一个的共有多少人？","options":["77","63","66","61"],"answer":1,"explanation":"由三集合容斥公式：至少参加一个=22+22+33−7−6−6+5=63人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40157","module":"shuliang","prompt":"今年甲的年龄是乙的5倍，9年后甲的年龄是乙的4倍。乙今年多少岁？","options":["9","30","26","27"],"answer":3,"explanation":"设乙今年x岁，则甲为5x岁；9年后：5x+9=4(x+9)，解得x=27岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40158","module":"shuliang","prompt":"今年甲的年龄是乙的3倍，15年后甲的年龄是乙的2倍。乙今年多少岁？","options":["13","16","15","225"],"answer":2,"explanation":"设乙今年x岁，则甲为3x岁；15年后：3x+15=2(x+15)，解得x=15岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40159","module":"shuliang","prompt":"一列火车长175米，以每秒29米的速度通过一座长2755米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["6","101","95","104"],"answer":1,"explanation":"火车完全过桥需行驶175+2755=2930米，时间=2930÷29=101秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40160","module":"shuliang","prompt":"某淘汰赛共有11支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["20","11","5","10"],"answer":3,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰10支，故共需10场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40161","module":"shuliang","prompt":"两个正数的和为28，要使它们的乘积最大，则最大的乘积是多少？","options":["198","28","196","193"],"answer":2,"explanation":"两数和一定时，两数相等时乘积最大，均为28÷2=14，最大乘积=14×14=196。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40162","module":"shuliang","prompt":"某商品进价每件50元，售价每件90元时每天可卖108件。售价每提高1元，每天少卖2件。要使每天利润最大，售价应定为每件多少元？","options":["90","99","94","97"],"answer":3,"explanation":"设售价提高k元，每天利润=(40+k)×(108−2k)，是关于k的二次函数，当k=7时最大，此时售价=90+7=97元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40163","module":"shuliang","prompt":"一只手表每小时比标准时间快20秒。若以标准时间为准，这只手表一昼夜（24小时）共快多少分钟？","options":["10","8","7","24"],"answer":1,"explanation":"每小时快20秒，一昼夜24小时共快24×20=480秒=8分钟。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40164","module":"shuliang","prompt":"某商品进价600元，售价672元。该商品的利润率是多少？","options":["24%","14%","4%","12%"],"answer":3,"explanation":"利润=672−600=72元，利润率=72÷600×100%=12%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40165","module":"shuliang","prompt":"一个平底锅每次最多可以烙2张饼，每张饼两面都要烙，每面需要2分钟。烙9张饼最少需要多少分钟？","options":["36","18","20","17"],"answer":1,"explanation":"共需烙9×2=18面，每次最多烙2面，至少9锅次，最少9×2=18分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40166","module":"shuliang","prompt":"某班共有59人，参加数学竞赛的有26人，参加作文竞赛的有25人，参加英语竞赛的有24人；同时参加数学和作文的有9人，参加数学和英语的有4人，参加作文和英语的有10人，三项都参加的有4人。三项竞赛都不参加的有多少人？","options":["23","6","3","59"],"answer":2,"explanation":"至少参加一项的有26+25+24−9−4−10+4=56人，都不参加的有59−56=3人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40167","module":"shuliang","prompt":"一项工程，老周先做5天、老吴再做19天恰好完成；若老吴先做5天、老周再做19天也恰好完成。两人合作，需要多少天完成？","options":["14","24","12","13"],"answer":2,"explanation":"设老周每天完成x、老吴每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=24÷2=12天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40168","module":"shuliang","prompt":"甲接水需要5分钟，乙接水需要11分钟，丙接水需要6分钟，丁接水需要7分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["29","69","58","34"],"answer":3,"explanation":"让用时短的人先接水可使总等待时间最短。按5、6、7、11的顺序，总等待=5×3+6×2+7×1+11×0=34分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40169","module":"shuliang","prompt":"两个数的和是164，差是14。这两个数中较大的数是多少？","options":["68","96","89","164"],"answer":2,"explanation":"小数=（和−差）÷2=75，大数=（和+差）÷2=89。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40170","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才19岁。”乙对甲说：“当我到你这么大时，你就25岁了。”甲今年多少岁？","options":["25","21","23","24"],"answer":2,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙19岁，即乙现在为x+d；乙到甲现在这么大时甲25岁，即甲现在为y−d。由y−d−(x+d)=d得d=(25−19)÷3=2，甲今年=25−2=23岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40171","module":"shuliang","prompt":"已知等差数列的前10项和为300，前20项和为1200，则该数列的公差是多少？","options":["6","7","5","1"],"answer":0,"explanation":"S20−2×S10=(1200)−2×(300)=600=100d（第11到20项之和比前10项之和多100d），故d=6。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40172","module":"shuliang","prompt":"轿车、面包车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地37千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地63千米处。问A、B两地相距多少千米？","options":["72","98","87","111"],"answer":2,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且轿车行37千米，故第二次相遇时轿车共行111千米。111大于一个全程而小于两个全程，说明轿车已从B地折返，其位置距A地为2S−111（S为全程）。由2S−111=63，解得S=87千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40173","module":"shuliang","prompt":"已知等差数列的首项为5，公差为5，则它的前9项之和是多少？","options":["405","225","228","217"],"answer":1,"explanation":"第9项=5+(9-1)×5=45，前9项和=n×(首项+末项)÷2=9×(5+45)÷2=225。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40174","module":"shuliang","prompt":"一个平底锅每次最多可以烙4张饼，每张饼两面都要烙，每面需要4分钟。烙10张饼最少需要多少分钟？","options":["24","80","20","22"],"answer":2,"explanation":"共需烙10×2=20面，每次最多烙4面，至少5锅次，最少5×4=20分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40175","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有20人，参加物理组的有40人，参加化学组的有37人；同时参加数学和物理的有12人，参加数学和化学的有10人，参加物理和化学的有5人，三个组都参加的有3人。三个组至少参加一个的共有多少人？","options":["78","97","73","69"],"answer":2,"explanation":"由三集合容斥公式：至少参加一个=20+40+37−12−10−5+3=73人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40176","module":"shuliang","prompt":"甲数与乙数之比为3:4，乙数与丙数之比为4:5。甲数是丙数的多少倍？","options":["5/3","3/5","13/20","15/16"],"answer":1,"explanation":"甲:丙=3×4:4×5=12:20，甲是丙的3/5倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40177","module":"shuliang","prompt":"6个正整数之和为34（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["6","9","5","8"],"answer":0,"explanation":"最大数最小时各数尽量平均，34÷6=5余4，故最大数至少为6（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40178","module":"shuliang","prompt":"一个长方体的长、宽、高分别为11厘米、8厘米、2厘米，它的表面积是多少平方厘米？","options":["21","176","252","42"],"answer":2,"explanation":"长方体表面积=2×（长×宽+宽×高+长×高）=2×(88+16+22)=252平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40179","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需38小时，逆流需46小时，两码头相距874千米。该轮船在静水中的速度是多少千米/小时？","options":["23","2","21","19"],"answer":2,"explanation":"顺流速度=874÷38=23千米/小时，逆流速度=874÷46=19千米/小时；静水速度=(23+19)÷2=21千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40180","module":"shuliang","prompt":"一项工程，甲的工作效率是乙的2倍，两人合作18天完成。若由甲单独做，需要多少天完成？","options":["18","27","29","26"],"answer":1,"explanation":"设乙每天完成1份，则甲每天完成2份，两人合作每天3份，工程总量为18×3=54份；甲单独做需54÷2=27天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40181","module":"shuliang","prompt":"某单位组织140人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["1600","1493","1266","1360"],"answer":3,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为1360元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40183","module":"shuliang","prompt":"甲数与乙数之比为4:3，乙数与丙数之比为3:2。甲数是丙数的多少倍？","options":["3","1/2","13/6","2"],"answer":3,"explanation":"甲:丙=4×3:3×2=12:6，甲是丙的2倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40184","module":"shuliang","prompt":"一列火车长167米，以每秒31米的速度通过一座长1705米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["55","5","60","63"],"answer":2,"explanation":"火车完全过桥需行驶167+1705=1872米，时间=1872÷31=60秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40185","module":"shuliang","prompt":"甲接水需要7分钟，乙接水需要8分钟，丙接水需要5分钟，丁接水需要10分钟，戊接水需要6分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["36","102","91","60"],"answer":3,"explanation":"让用时短的人先接水可使总等待时间最短。按5、6、7、8、10的顺序，总等待=5×4+6×3+7×2+8×1+10×0=60分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40186","module":"shuliang","prompt":"6个正整数之和为46（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["41","46","42","40"],"answer":0,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=46−5×1=41。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40187","module":"shuliang","prompt":"客车、货车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地74千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地18千米处。问A、B两地相距多少千米？","options":["222","142","100","120"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且客车行74千米，故第二次相遇时客车共行222千米。222大于一个全程而小于两个全程，说明客车已从B地折返，其位置距A地为2S−222（S为全程）。由2S−222=18，解得S=120千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40188","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行33千米，按原路返回时每小时行66千米。该车往返全程的平均速度是多少千米/小时？","options":["44","49","47","43"],"answer":0,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/33+1/66)=2×33×66÷(33+66)=44千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40189","module":"shuliang","prompt":"一列火车长146米，以每秒18米的速度通过一座长1116米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["70","8","62","73"],"answer":0,"explanation":"火车完全过桥需行驶146+1116=1262米，时间=1262÷18=70秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40190","module":"shuliang","prompt":"快车和慢车的速度比为7:2，两人同时同地同向出发赛跑，当快车到达终点时，慢车距终点还有40米。赛道全程是多少米？","options":["280","100","18","56"],"answer":3,"explanation":"同一时间内路程比等于速度比，慢车走了全程的2/7，还差全程的5/7=40米，故全程=40×7÷5=56米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40191","module":"shuliang","prompt":"某商品按进价加价40%定价，然后按7折出售，仍可获利。该商品的利润率是多少？","options":["28%","-2%","-1%","7%"],"answer":1,"explanation":"设进价为100，售价=100×(1+40%)×7/10=98，利润率=98−100=-2%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40192","module":"shuliang","prompt":"6个正整数之和为27（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["4","7","3","5"],"answer":3,"explanation":"最大数最小时各数尽量平均，27÷6=4余3，故最大数至少为5（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40193","module":"shuliang","prompt":"两个数的和是68，差是28。这两个数中较大的数是多少？","options":["68","62","6","48"],"answer":3,"explanation":"小数=（和−差）÷2=20，大数=（和+差）÷2=48。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40194","module":"shuliang","prompt":"一项工程，师傅甲单独做需要15天完成，师傅乙单独做需要20天完成。现两人合作3天后，剩余部分由师傅乙单独完成，还需要多少天？","options":["13","17","15","20"],"answer":0,"explanation":"两人每天合作完成1/15+1/20=(15+20)/300，3天完成105/300，剩195/300；师傅乙每天完成1/20，还需20×195/300=13天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40195","module":"shuliang","prompt":"一个正方形的边长扩大到原来的2倍，它的面积扩大到原来的多少倍？","options":["4","2","6","8"],"answer":0,"explanation":"边长扩大2倍，面积扩大2×2=4倍。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40196","module":"shuliang","prompt":"某商品按定价出售每件可赚20元，若按定价的9折出售，每件将亏损50元。该商品的进价是多少元？","options":["70","697","643","680"],"answer":3,"explanation":"设进价为C，定价为C+20；9折售价为9/10×(C+20)=C−50，解得C=680元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40197","module":"shuliang","prompt":"甲种卡车每次可运7吨货物，耗油8升；乙种卡车每次可运2吨货物，耗油5升。现要运送49吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["58","56","53","120"],"answer":1,"explanation":"甲车每吨耗油8/7升，乙车每吨耗油5/2升，甲车更省。尽量用甲车：7车次运49吨，余0吨用乙车0次，共耗油56升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40198","module":"shuliang","prompt":"甲种卡车每次可运7吨货物，耗油12升；乙种卡车每次可运2吨货物，耗油6升。现要运送84吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["150","144","138","252"],"answer":1,"explanation":"甲车每吨耗油12/7升，乙车每吨耗油6/2升，甲车更省。尽量用甲车：12车次运84吨，余0吨用乙车0次，共耗油144升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40199","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油9升；乙种卡车每次可运3吨货物，耗油7升。现要运送72吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["168","114","104","108"],"answer":3,"explanation":"甲车每吨耗油9/6升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：12车次运72吨，余0吨用乙车0次，共耗油108升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40200","module":"shuliang","prompt":"某商品进价每件20元，售价每件60元时每天可卖78件。售价每提高1元，每天少卖3件。要使每天利润最大，售价应定为每件多少元？","options":["53","55","52","60"],"answer":0,"explanation":"设售价提高k元，每天利润=(40+k)×(78−3k)，是关于k的二次函数，当k=-7时最大，此时售价=60+-7=53元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40201","module":"shuliang","prompt":"一项工程，师傅甲的工作效率是师傅乙的2倍，两人合作10天完成。若由师傅甲单独做，需要多少天完成？","options":["15","10","18","13"],"answer":0,"explanation":"设师傅乙每天完成1份，则师傅甲每天完成2份，两人合作每天3份，工程总量为10×3=30份；师傅甲单独做需30÷2=15天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40202","module":"shuliang","prompt":"已知等差数列的前10项和为295，前20项和为1090，则该数列的公差是多少？","options":["5","7","4","1"],"answer":0,"explanation":"S20−2×S10=(1090)−2×(295)=500=100d（第11到20项之和比前10项之和多100d），故d=5。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40203","module":"shuliang","prompt":"在一个边长为14厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["43","196","49","41"],"answer":0,"explanation":"正方形面积=196平方厘米，最大圆半径为7厘米，圆面积=3.14×7²=153平方厘米，剩余=196−153=43平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40204","module":"shuliang","prompt":"某淘汰赛共有31支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["15","31","30","60"],"answer":2,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰30支，故共需30场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40205","module":"shuliang","prompt":"4个正整数之和为17（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["6","5","3","4"],"answer":1,"explanation":"最大数最小时各数尽量平均，17÷4=4余1，故最大数至少为5（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40206","module":"shuliang","prompt":"已知等差数列的前10项和为340，前20项和为1280，则该数列的公差是多少？","options":["8","6","5","1"],"answer":1,"explanation":"S20−2×S10=(1280)−2×(340)=600=100d（第11到20项之和比前10项之和多100d），故d=6。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40207","module":"shuliang","prompt":"某淘汰赛共有12支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["11","12","6","13"],"answer":0,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰11支，故共需11场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40208","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需44小时，逆流需68小时，两码头相距1496千米。该轮船在静水中的速度是多少千米/小时？","options":["28","6","34","26"],"answer":0,"explanation":"顺流速度=1496÷44=34千米/小时，逆流速度=1496÷68=22千米/小时；静水速度=(34+22)÷2=28千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40209","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行30千米，按原路返回时每小时行42千米。该车往返全程的平均速度是多少千米/小时？","options":["42","36","34","35"],"answer":3,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/30+1/42)=2×30×42÷(30+42)=35千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40210","module":"shuliang","prompt":"某商场促销“满300减30”，小明购买了标价900元的商品（满足优惠条件）。实际付款相当于打几折？","options":["10折","9折","8折","1折"],"answer":1,"explanation":"优惠后实付900−3×30=810元，810÷900=9/10，相当于打9折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40211","module":"shuliang","prompt":"一项工程，甲单独做需要10天完成，乙单独做需要15天完成。现两人合作4天后，剩余部分由乙单独完成，还需要多少天？","options":["11","5","6","15"],"answer":1,"explanation":"两人每天合作完成1/10+1/15=(10+15)/150，4天完成100/150，剩50/150；乙每天完成1/15，还需15×50/150=5天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40212","module":"shuliang","prompt":"某商品进价400元，售价748元。该商品的利润率是多少？","options":["87%","88%","84%","174%"],"answer":0,"explanation":"利润=748−400=348元，利润率=348÷400×100%=87%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40213","module":"shuliang","prompt":"今年甲的年龄是乙的4倍，7年后甲的年龄是乙的3倍。乙今年多少岁？","options":["14","15","13","7"],"answer":0,"explanation":"设乙今年x岁，则甲为4x岁；7年后：4x+7=3(x+7)，解得x=14岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40214","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有27人，参加羽毛球赛的有35人，参加乒乓球赛的有24人；同时参加篮球和羽毛球的有6人，参加篮球和乒乓球的有9人，参加羽毛球和乒乓球的有11人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["51","46","43","64"],"answer":1,"explanation":"只参加篮球=27−6−9+4=16人；同理只参加羽毛球=22人，只参加乒乓球=8人；合计16+22+8=46人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40215","module":"shuliang","prompt":"已知等差数列的首项为8，公差为4，则它的第18项是多少？","options":["72","80","76","77"],"answer":2,"explanation":"等差数列第n项=首项+(n−1)×公差=8+(18-1)×4=76。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40216","module":"shuliang","prompt":"小明和小红的速度比为5:2，两人同时同地同向出发赛跑，当小明到达终点时，小红距终点还有30米。赛道全程是多少米？","options":["150","63","9","50"],"answer":3,"explanation":"同一时间内路程比等于速度比，小红走了全程的2/5，还差全程的3/5=30米，故全程=30×5÷3=50米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40217","module":"shuliang","prompt":"某商品进价每件50元，售价每件90元时每天可卖104件。售价每提高1元，每天少卖4件。要使每天利润最大，售价应定为每件多少元？","options":["90","84","81","83"],"answer":3,"explanation":"设售价提高k元，每天利润=(40+k)×(104−4k)，是关于k的二次函数，当k=-7时最大，此时售价=90+-7=83元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40218","module":"shuliang","prompt":"把120个名额按6:9:5的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["90","30","54","66"],"answer":2,"explanation":"总份数=6+9+5=20，每份120÷20=6个，最多的班级分得9×6=54个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40219","module":"shuliang","prompt":"4个正整数之和为34（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["9","10","7","8"],"answer":0,"explanation":"最大数最小时各数尽量平均，34÷4=8余2，故最大数至少为9（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40220","module":"shuliang","prompt":"今年父子二人年龄之和是80岁，父亲年龄是儿子年龄的4倍。父亲今年多少岁？","options":["61","16","70","64"],"answer":3,"explanation":"儿子年龄为1份，父亲为4份，共5份；儿子=80÷5=16岁，父亲=4×16=64岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40221","module":"shuliang","prompt":"一项工程，一队单独做需要20天完成，二队单独做需要30天完成。两人（队）合作，需要多少天完成？","options":["10","50","12","25"],"answer":2,"explanation":"把工程总量看作1，两人效率之和为1/20+1/30=(20+30)/600，合作需要600÷(20+30)=12天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40222","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有29人，参加羽毛球赛的有24人，参加乒乓球赛的有31人；同时参加篮球和羽毛球的有7人，参加篮球和乒乓球的有6人，参加羽毛球和乒乓球的有6人，三项都参加的有5人。只参加其中一项比赛的有多少人？","options":["64","61","59","70"],"answer":1,"explanation":"只参加篮球=29−7−6+5=21人；同理只参加羽毛球=16人，只参加乒乓球=24人；合计21+16+24=61人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40223","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才17岁。”乙对甲说：“当我到你这么大时，你就56岁了。”甲今年多少岁？","options":["41","30","45","43"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙17岁，即乙现在为x+d；乙到甲现在这么大时甲56岁，即甲现在为y−d。由y−d−(x+d)=d得d=(56−17)÷3=13，甲今年=56−13=43岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40224","module":"shuliang","prompt":"已知等比数列的首项为2，公比为2，则它的第7项是多少？","options":["256","128","64","130"],"answer":1,"explanation":"等比数列第n项=首项×公比^(n−1)=2×2^(7-1)=128。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40225","module":"shuliang","prompt":"两个正数的和为30，要使它们的乘积最大，则最大的乘积是多少？","options":["226","30","225","222"],"answer":2,"explanation":"两数和一定时，两数相等时乘积最大，均为30÷2=15，最大乘积=15×15=225。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40226","module":"shuliang","prompt":"甲接水需要8分钟，乙接水需要6分钟，丙接水需要4分钟，丁接水需要7分钟，戊接水需要3分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["77","43","66","28"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按3、4、6、7、8的顺序，总等待=3×4+4×3+6×2+7×1+8×0=43分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40227","module":"shuliang","prompt":"一项工程，王师傅的工作效率是赵师傅的5/3倍，两人合作10天完成。若由王师傅单独做，需要多少天完成？","options":["30","16","17","10"],"answer":1,"explanation":"设赵师傅每天完成1份，则王师傅每天完成5/3份，两人合作每天8/3份，工程总量为10×8/3=80/3份；王师傅单独做需80/3÷5/3=16天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40228","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有31人，参加羽毛球赛的有25人，参加乒乓球赛的有29人；同时参加篮球和羽毛球的有9人，参加篮球和乒乓球的有12人，参加羽毛球和乒乓球的有11人，三项都参加的有5人。只参加其中一项比赛的有多少人？","options":["36","38","33","58"],"answer":0,"explanation":"只参加篮球=31−9−12+5=15人；同理只参加羽毛球=10人，只参加乒乓球=11人；合计15+10+11=36人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40229","module":"shuliang","prompt":"今天是星期一，再过124天是星期几？","options":["星期三","星期日","星期五","星期六"],"answer":3,"explanation":"124÷7=17余5，星期一往后推5天是星期六。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40230","module":"shuliang","prompt":"一列火车长182米，以每秒28米的速度通过一座长1512米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["63","6","54","60"],"answer":3,"explanation":"火车完全过桥需行驶182+1512=1694米，时间=1694÷28=60秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40231","module":"shuliang","prompt":"在一个边长为22厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["114","484","105","100"],"answer":2,"explanation":"正方形面积=484平方厘米，最大圆半径为11厘米，圆面积=3.14×11²=379平方厘米，剩余=484−379=105平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40232","module":"shuliang","prompt":"把60个名额按4:3:3的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["18","24","42","36"],"answer":1,"explanation":"总份数=4+3+3=10，每份60÷10=6个，最多的班级分得4×6=24个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40233","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是42立方分米。圆锥的体积是多少立方分米？","options":["42","14","21","84"],"answer":1,"explanation":"等底等高的圆锥体积是圆柱的1/3，即42÷3=14立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40234","module":"shuliang","prompt":"6个正整数之和为65（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["11","12","9","10"],"answer":0,"explanation":"最大数最小时各数尽量平均，65÷6=10余5，故最大数至少为11（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40235","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有26人，参加物理组的有32人，参加化学组的有21人；同时参加数学和物理的有6人，参加数学和化学的有5人，参加物理和化学的有8人，三个组都参加的有2人。三个组至少参加一个的共有多少人？","options":["79","62","63","58"],"answer":1,"explanation":"由三集合容斥公式：至少参加一个=26+32+21−6−5−8+2=62人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40236","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油11升；乙种卡车每次可运2吨货物，耗油5升。现要运送48吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["96","88","85","120"],"answer":1,"explanation":"甲车每吨耗油11/6升，乙车每吨耗油5/2升，甲车更省。尽量用甲车：8车次运48吨，余0吨用乙车0次，共耗油88升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40237","module":"shuliang","prompt":"快车、慢车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地78千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地30千米处。问A、B两地相距多少千米？","options":["106","147","132","234"],"answer":2,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且快车行78千米，故第二次相遇时快车共行234千米。234大于一个全程而小于两个全程，说明快车已从B地折返，其位置距A地为2S−234（S为全程）。由2S−234=30，解得S=132千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40238","module":"shuliang","prompt":"某商品按进价加价80%定价，然后按9折出售，仍可获利。该商品的利润率是多少？","options":["58%","72%","65%","62%"],"answer":3,"explanation":"设进价为100，售价=100×(1+80%)×9/10=162，利润率=162−100=62%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40239","module":"shuliang","prompt":"某淘汰赛共有26支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["50","26","13","25"],"answer":3,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰25支，故共需25场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40240","module":"shuliang","prompt":"A接水需要9分钟，B接水需要7分钟，C接水需要10分钟，D接水需要2分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["29","64","54","28"],"answer":0,"explanation":"让用时短的人先接水可使总等待时间最短。按2、7、9、10的顺序，总等待=2×3+7×2+9×1+10×0=29分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40241","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供20头牛吃21天，或供36头牛吃9天。若放29头牛，可以吃多少天？","options":["12","15","11","13"],"answer":0,"explanation":"每天长草量=(36×9−20×21)÷(9−21)=8份，原有草量=20×21−8×21=252份；29头牛每天净消耗29−8=21份，可吃252÷21=12天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40242","module":"shuliang","prompt":"A接水需要6分钟，B接水需要4分钟，C接水需要12分钟，D接水需要11分钟，E接水需要5分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["97","54","87","38"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按4、5、6、11、12的顺序，总等待=4×4+5×3+6×2+11×1+12×0=54分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40243","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供11头牛吃24天，或供23头牛吃8天。若放29头牛，可以吃多少天？","options":["10","9","5","6"],"answer":3,"explanation":"每天长草量=(23×8−11×24)÷(8−24)=5份，原有草量=11×24−5×24=144份；29头牛每天净消耗29−5=24份，可吃144÷24=6天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40244","module":"shuliang","prompt":"某商品进价每件20元，售价每件40元时每天可卖110件。售价每提高1元，每天少卖5件。要使每天利润最大，售价应定为每件多少元？","options":["41","43","38","40"],"answer":0,"explanation":"设售价提高k元，每天利润=(20+k)×(110−5k)，是关于k的二次函数，当k=1时最大，此时售价=40+1=41元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40245","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供11头牛吃18天，或供23头牛吃6天。若放41头牛，可以吃多少天？","options":["5","4","2","3"],"answer":3,"explanation":"每天长草量=(23×6−11×18)÷(6−18)=5份，原有草量=11×18−5×18=108份；41头牛每天净消耗41−5=36份，可吃108÷36=3天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40246","module":"shuliang","prompt":"时钟3点10分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["28","46","35","145"],"answer":2,"explanation":"时针与12点方向夹角为30×3+0.5×10=95.0度，分针与12点方向夹角为6×10=60度，两针夹角为35度，取小于180度的角为35.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40247","module":"shuliang","prompt":"甲数与乙数之比为3:2，乙数与丙数之比为2:3。甲数是丙数的多少倍？","options":["7/6","1","2","3"],"answer":1,"explanation":"甲:丙=3×2:2×3=6:6，甲是丙的1倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40248","module":"shuliang","prompt":"一项工程，张师傅单独做需要13天完成，李师傅单独做需要26天完成。现两人合作2天后，剩余部分由李师傅单独完成，还需要多少天？","options":["24","20","23","26"],"answer":1,"explanation":"两人每天合作完成1/13+1/26=(13+26)/338，2天完成78/338，剩260/338；李师傅每天完成1/26，还需26×260/338=20天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40249","module":"shuliang","prompt":"今天是星期六，再过129天是星期几？","options":["星期四","星期三","星期一","星期二"],"answer":3,"explanation":"129÷7=18余3，星期六往后推3天是星期二。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40250","module":"shuliang","prompt":"甲数是乙数的4倍，两数之和是300。乙数是多少？","options":["62","240","60","59"],"answer":2,"explanation":"乙数为1份，甲数为4份，共5份；乙数=300÷5=60。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40251","module":"shuliang","prompt":"今年父子二人年龄之和是99岁，父亲年龄是儿子年龄的2倍。父亲今年多少岁？","options":["62","33","68","66"],"answer":3,"explanation":"儿子年龄为1份，父亲为2份，共3份；儿子=99÷3=33岁，父亲=2×33=66岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40252","module":"shuliang","prompt":"小明在小红后方190千米处，两人同时同向出发。小明每小时行77千米，小红每小时行39千米，经过多少小时小明追上小红？","options":["7","6","5","190"],"answer":2,"explanation":"每小时小明比小红多行77-39=38千米，追及时间=190÷38=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40253","module":"shuliang","prompt":"一项工程，王师傅单独做需要14天完成，赵师傅单独做需要28天完成。现两人合作5天后，剩余部分由赵师傅单独完成，还需要多少天？","options":["28","23","16","13"],"answer":3,"explanation":"两人每天合作完成1/14+1/28=(14+28)/392，5天完成210/392，剩182/392；赵师傅每天完成1/28，还需28×182/392=13天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40254","module":"shuliang","prompt":"一列火车长283米，以每秒35米的速度通过一座长4095米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["8","125","117","126"],"answer":1,"explanation":"火车完全过桥需行驶283+4095=4378米，时间=4378÷35=125秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40255","module":"shuliang","prompt":"某班共有55人，参加数学竞赛的有23人，参加作文竞赛的有22人，参加英语竞赛的有28人；同时参加数学和作文的有7人，参加数学和英语的有10人，参加作文和英语的有9人，三项都参加的有4人。三项竞赛都不参加的有多少人？","options":["6","4","26","55"],"answer":1,"explanation":"至少参加一项的有23+22+28−7−10−9+4=51人，都不参加的有55−51=4人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40256","module":"shuliang","prompt":"4个正整数之和为39（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["35","39","36","34"],"answer":2,"explanation":"要使最大的数最大，其余3个数都取最小值1，故最大数=39−3×1=36。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40257","module":"shuliang","prompt":"4个正整数之和为51（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["52","51","48","47"],"answer":2,"explanation":"要使最大的数最大，其余3个数都取最小值1，故最大数=51−3×1=48。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40258","module":"shuliang","prompt":"某单位组织112人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["1262","1080","1018","1200"],"answer":1,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为1080元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40259","module":"shuliang","prompt":"甲种卡车每次可运7吨货物，耗油10升；乙种卡车每次可运3吨货物，耗油7升。现要运送56吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["80","85","78","126"],"answer":0,"explanation":"甲车每吨耗油10/7升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：8车次运56吨，余0吨用乙车0次，共耗油80升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40260","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油11升；乙种卡车每次可运2吨货物，耗油4升。现要运送66吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["125","121","115","132"],"answer":1,"explanation":"甲车每吨耗油11/6升，乙车每吨耗油4/2升，甲车更省。尽量用甲车：11车次运66吨，余0吨用乙车0次，共耗油121升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40261","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有30人，参加物理组的有22人，参加化学组的有38人；同时参加数学和物理的有11人，参加数学和化学的有6人，参加物理和化学的有9人，三个组都参加的有5人。三个组至少参加一个的共有多少人？","options":["70","90","69","65"],"answer":2,"explanation":"由三集合容斥公式：至少参加一个=30+22+38−11−6−9+5=69人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40262","module":"shuliang","prompt":"某淘汰赛共有24支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["24","23","12","25"],"answer":1,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰23支，故共需23场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40263","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有32人，参加羽毛球赛的有20人，参加乒乓球赛的有30人；同时参加篮球和羽毛球的有9人，参加篮球和乒乓球的有6人，参加羽毛球和乒乓球的有10人，三项都参加的有6人。只参加其中一项比赛的有多少人？","options":["63","52","47","50"],"answer":3,"explanation":"只参加篮球=32−9−6+6=23人；同理只参加羽毛球=7人，只参加乒乓球=20人；合计23+7+20=50人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40264","module":"shuliang","prompt":"客车和货车分别从相距750千米的两地同时出发，相向而行。客车每小时行61千米，货车每小时行64千米，经过多少小时两车相遇？","options":["5","8","6","7"],"answer":2,"explanation":"两车速度之和为61+64=125千米/小时，相遇时间=750÷125=6小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40265","module":"shuliang","prompt":"今年甲的年龄是乙的3倍，12年后甲的年龄是乙的2倍。乙今年多少岁？","options":["15","12","10","144"],"answer":1,"explanation":"设乙今年x岁，则甲为3x岁；12年后：3x+12=2(x+12)，解得x=12岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40266","module":"shuliang","prompt":"已知等差数列的首项为4，公差为2，则它的第9项是多少？","options":["22","20","18","21"],"answer":1,"explanation":"等差数列第n项=首项+(n−1)×公差=4+(9-1)×2=20。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40267","module":"shuliang","prompt":"一项工程，师傅甲先做14天、师傅乙再做20天恰好完成；若师傅乙先做14天、师傅甲再做20天也恰好完成。两人合作，需要多少天完成？","options":["34","17","6","18"],"answer":1,"explanation":"设师傅甲每天完成x、师傅乙每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=34÷2=17天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40268","module":"shuliang","prompt":"已知等差数列的前10项和为285，前20项和为1070，则该数列的公差是多少？","options":["5","7","4","1"],"answer":0,"explanation":"S20−2×S10=(1070)−2×(285)=500=100d（第11到20项之和比前10项之和多100d），故d=5。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40269","module":"shuliang","prompt":"客车、货车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地26千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地66千米处。问A、B两地相距多少千米？","options":["78","88","52","72"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且客车行26千米，故第二次相遇时客车共行78千米。78大于一个全程而小于两个全程，说明客车已从B地折返，其位置距A地为2S−78（S为全程）。由2S−78=66，解得S=72千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40270","module":"shuliang","prompt":"一项工程，一队先做9天、二队再做19天恰好完成；若二队先做9天、一队再做19天也恰好完成。两人合作，需要多少天完成？","options":["15","28","10","14"],"answer":3,"explanation":"设一队每天完成x、二队每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=28÷2=14天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40271","module":"shuliang","prompt":"张三、李四两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地39千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地39千米处。问A、B两地相距多少千米？","options":["78","104","57","117"],"answer":0,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且张三行39千米，故第二次相遇时张三共行117千米。117大于一个全程而小于两个全程，说明张三已从B地折返，其位置距A地为2S−117（S为全程）。由2S−117=39，解得S=78千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40272","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有41人，参加数学兴趣小组的有26人，两个小组都参加的有19人。两个小组至少参加一个的共有多少人？","options":["48","67","86","15"],"answer":0,"explanation":"都参加的19人被算了两次，需减去一次，故至少参加一个的人数=41+26−19=48人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40273","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有38人，参加物理组的有36人，参加化学组的有37人；同时参加数学和物理的有8人，参加数学和化学的有12人，参加物理和化学的有8人，三个组都参加的有5人。三个组至少参加一个的共有多少人？","options":["111","88","89","87"],"answer":1,"explanation":"由三集合容斥公式：至少参加一个=38+36+37−8−12−8+5=88人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40274","module":"shuliang","prompt":"一列火车长270米，以每秒21米的速度通过一座长1449米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["69","12","81","84"],"answer":2,"explanation":"火车完全过桥需行驶270+1449=1719米，时间=1719÷21=81秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40275","module":"shuliang","prompt":"一项工程，甲先做10天、乙再做12天恰好完成；若乙先做10天、甲再做12天也恰好完成。两人合作，需要多少天完成？","options":["22","11","2","12"],"answer":1,"explanation":"设甲每天完成x、乙每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=22÷2=11天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40276","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有32人，参加羽毛球赛的有30人，参加乒乓球赛的有34人；同时参加篮球和羽毛球的有8人，参加篮球和乒乓球的有10人，参加羽毛球和乒乓球的有12人，三项都参加的有3人。只参加其中一项比赛的有多少人？","options":["49","45","42","69"],"answer":1,"explanation":"只参加篮球=32−8−10+3=17人；同理只参加羽毛球=13人，只参加乒乓球=15人；合计17+13+15=45人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40277","module":"shuliang","prompt":"A接水需要12分钟，B接水需要7分钟，C接水需要2分钟，D接水需要9分钟，E接水需要10分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["40","101","95","57"],"answer":3,"explanation":"让用时短的人先接水可使总等待时间最短。按2、7、9、10、12的顺序，总等待=2×4+7×3+9×2+10×1+12×0=57分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40278","module":"shuliang","prompt":"某商品按定价出售每件可赚50元，若按定价的9折出售，每件将亏损40元。该商品的进价是多少元？","options":["802","872","850","90"],"answer":2,"explanation":"设进价为C，定价为C+50；9折售价为9/10×(C+50)=C−40，解得C=850元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40279","module":"shuliang","prompt":"两个正数的和为8，要使它们的乘积最大，则最大的乘积是多少？","options":["8","16","17","15"],"answer":1,"explanation":"两数和一定时，两数相等时乘积最大，均为8÷2=4，最大乘积=4×4=16。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40280","module":"shuliang","prompt":"某商品进价每件40元，售价每件70元时每天可卖48件。售价每提高1元，每天少卖2件。要使每天利润最大，售价应定为每件多少元？","options":["68","67","66","70"],"answer":1,"explanation":"设售价提高k元，每天利润=(30+k)×(48−2k)，是关于k的二次函数，当k=-3时最大，此时售价=70+-3=67元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40281","module":"shuliang","prompt":"两个数的和是62，差是14。这两个数中较大的数是多少？","options":["62","45","17","38"],"answer":3,"explanation":"小数=（和−差）÷2=24，大数=（和+差）÷2=38。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40282","module":"shuliang","prompt":"两个数的和是156，差是32。这两个数中较大的数是多少？","options":["94","110","46","156"],"answer":0,"explanation":"小数=（和−差）÷2=62，大数=（和+差）÷2=94。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40283","module":"shuliang","prompt":"某商品按进价加价50%定价，然后按9折出售，仍可获利。该商品的利润率是多少？","options":["35%","45%","42%","30%"],"answer":0,"explanation":"设进价为100，售价=100×(1+50%)×9/10=135，利润率=135−100=35%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40284","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才12岁。”乙对甲说：“当我到你这么大时，你就24岁了。”甲今年多少岁？","options":["23","16","20","18"],"answer":2,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙12岁，即乙现在为x+d；乙到甲现在这么大时甲24岁，即甲现在为y−d。由y−d−(x+d)=d得d=(24−12)÷3=4，甲今年=24−4=20岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40285","module":"shuliang","prompt":"已知等差数列的前10项和为330，前20项和为1260，则该数列的公差是多少？","options":["5","7","6","1"],"answer":2,"explanation":"S20−2×S10=(1260)−2×(330)=600=100d（第11到20项之和比前10项之和多100d），故d=6。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40286","module":"shuliang","prompt":"一列火车长233米，以每秒31米的速度通过一座长2139米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["79","7","69","76"],"answer":3,"explanation":"火车完全过桥需行驶233+2139=2372米，时间=2372÷31=76秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40287","module":"shuliang","prompt":"A接水需要3分钟，B接水需要12分钟，C接水需要6分钟，D接水需要7分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["28","59","52","56"],"answer":0,"explanation":"让用时短的人先接水可使总等待时间最短。按3、6、7、12的顺序，总等待=3×3+6×2+7×1+12×0=28分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40288","module":"shuliang","prompt":"某商场促销“满200减60”，小明购买了标价1000元的商品（满足优惠条件）。实际付款相当于打几折？","options":["6折","8折","7折","3折"],"answer":2,"explanation":"优惠后实付1000−5×60=700元，700÷1000=7/10，相当于打7折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40289","module":"shuliang","prompt":"小明在小红后方20千米处，两人同时同向出发。小明每小时行82千米，小红每小时行72千米，经过多少小时小明追上小红？","options":["20","4","2","82"],"answer":2,"explanation":"每小时小明比小红多行82-72=10千米，追及时间=20÷10=2小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40290","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有29人，参加羽毛球赛的有28人，参加乒乓球赛的有22人；同时参加篮球和羽毛球的有7人，参加篮球和乒乓球的有7人，参加羽毛球和乒乓球的有11人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["41","43","40","58"],"answer":0,"explanation":"只参加篮球=29−7−7+4=19人；同理只参加羽毛球=14人，只参加乒乓球=8人；合计19+14+8=41人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40291","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才8岁。”乙对甲说：“当我到你这么大时，你就38岁了。”甲今年多少岁？","options":["18","28","30","26"],"answer":1,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙8岁，即乙现在为x+d；乙到甲现在这么大时甲38岁，即甲现在为y−d。由y−d−(x+d)=d得d=(38−8)÷3=10，甲今年=38−10=28岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40292","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有24人，参加数学兴趣小组的有25人，两个小组都参加的有19人。两个小组至少参加一个的共有多少人？","options":["68","49","30","1"],"answer":2,"explanation":"都参加的19人被算了两次，需减去一次，故至少参加一个的人数=24+25−19=30人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40293","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有37人，参加数学兴趣小组的有37人，两个小组都参加的有32人。两个小组至少参加一个的共有多少人？","options":["74","42","106","0"],"answer":1,"explanation":"都参加的32人被算了两次，需减去一次，故至少参加一个的人数=37+37−32=42人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40294","module":"shuliang","prompt":"同一时刻，一根6米高的标杆在阳光下的影长为4米，附近一棵大树的影长为16米。这棵大树的高度是多少米？","options":["25","22","24","16"],"answer":2,"explanation":"同一时刻物高与影长成正比，树高=6×16÷4=24米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40295","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有23人，参加物理组的有30人，参加化学组的有24人；同时参加数学和物理的有6人，参加数学和化学的有8人，参加物理和化学的有12人，三个组都参加的有3人。三个组至少参加一个的共有多少人？","options":["59","77","54","53"],"answer":2,"explanation":"由三集合容斥公式：至少参加一个=23+30+24−6−8−12+3=54人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40296","module":"shuliang","prompt":"某小组共有10名成员，现从中随机选出3名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["56","120","64","67"],"answer":2,"explanation":"从10人中选3人共C(10,3)=120种；甲、乙都不入选有C(8,3)=56种；故至少一人入选共120−56=64种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40297","module":"shuliang","prompt":"已知等差数列的前10项和为150，前20项和为500，则该数列的公差是多少？","options":["2","3","1","35"],"answer":0,"explanation":"S20−2×S10=(500)−2×(150)=200=100d（第11到20项之和比前10项之和多100d），故d=2。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40298","module":"shuliang","prompt":"张三、李四两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地35千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地87千米处。问A、B两地相距多少千米？","options":["105","107","68","96"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且张三行35千米，故第二次相遇时张三共行105千米。105大于一个全程而小于两个全程，说明张三已从B地折返，其位置距A地为2S−105（S为全程）。由2S−105=87，解得S=96千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40299","module":"shuliang","prompt":"两个数的和是178，差是20。这两个数中较大的数是多少？","options":["99","109","69","178"],"answer":0,"explanation":"小数=（和−差）÷2=79，大数=（和+差）÷2=99。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40300","module":"shuliang","prompt":"彩旗按“红、黄、蓝”的顺序循环排列，第82面彩旗是什么颜色？","options":["蓝","黄","红","绿"],"answer":2,"explanation":"周期为3，82÷3=27余1，第82面旗对应周期中的第1个，即“红”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40301","module":"shuliang","prompt":"一项工程，一队的工作效率是二队的4倍，两人合作24天完成。若由一队单独做，需要多少天完成？","options":["24","30","33","28"],"answer":1,"explanation":"设二队每天完成1份，则一队每天完成4份，两人合作每天5份，工程总量为24×5=120份；一队单独做需120÷4=30天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40302","module":"shuliang","prompt":"今天是星期三，再过69天是星期几？","options":["星期四","星期三","星期一","星期二"],"answer":3,"explanation":"69÷7=9余6，星期三往后推6天是星期二。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40303","module":"shuliang","prompt":"某商场促销“满300减30”，小明购买了标价600元的商品（满足优惠条件）。实际付款相当于打几折？","options":["1折","10折","8折","9折"],"answer":3,"explanation":"优惠后实付600−2×30=540元，540÷600=9/10，相当于打9折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40304","module":"shuliang","prompt":"客车和货车分别从相距312千米的两地同时出发，相向而行。客车每小时行30千米，货车每小时行48千米，经过多少小时两车相遇？","options":["3","6","4","5"],"answer":2,"explanation":"两车速度之和为30+48=78千米/小时，相遇时间=312÷78=4小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40305","module":"shuliang","prompt":"某商品进价每件30元，售价每件50元时每天可卖156件。售价每提高1元，每天少卖6件。要使每天利润最大，售价应定为每件多少元？","options":["50","57","52","53"],"answer":3,"explanation":"设售价提高k元，每天利润=(20+k)×(156−6k)，是关于k的二次函数，当k=3时最大，此时售价=50+3=53元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40306","module":"shuliang","prompt":"已知等差数列的前10项和为160，前20项和为520，则该数列的公差是多少？","options":["36","3","1","2"],"answer":3,"explanation":"S20−2×S10=(520)−2×(160)=200=100d（第11到20项之和比前10项之和多100d），故d=2。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40308","module":"shuliang","prompt":"轿车和面包车分别从相距218千米的两地同时出发，相向而行。轿车每小时行68千米，面包车每小时行41千米，经过多少小时两车相遇？","options":["2","3","1","68"],"answer":0,"explanation":"两车速度之和为68+41=109千米/小时，相遇时间=218÷109=2小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40309","module":"shuliang","prompt":"4个正整数之和为40（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["10","11","9","13"],"answer":0,"explanation":"最大数最小时各数尽量平均，40÷4=10余0，故最大数至少为10（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40311","module":"shuliang","prompt":"甲种卡车每次可运8吨货物，耗油15升；乙种卡车每次可运2吨货物，耗油5升。现要运送96吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["180","188","175","240"],"answer":0,"explanation":"甲车每吨耗油15/8升，乙车每吨耗油5/2升，甲车更省。尽量用甲车：12车次运96吨，余0吨用乙车0次，共耗油180升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40312","module":"shuliang","prompt":"快车、慢车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地82千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地24千米处。问A、B两地相距多少千米？","options":["155","135","111","246"],"answer":1,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且快车行82千米，故第二次相遇时快车共行246千米。246大于一个全程而小于两个全程，说明快车已从B地折返，其位置距A地为2S−246（S为全程）。由2S−246=24，解得S=135千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40313","module":"shuliang","prompt":"某商品按进价加价70%定价，然后按9折出售，仍可获利。该商品的利润率是多少？","options":["53%","63%","55%","49%"],"answer":0,"explanation":"设进价为100，售价=100×(1+70%)×9/10=153，利润率=153−100=53%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40314","module":"shuliang","prompt":"一项工程，王师傅先做5天、赵师傅再做17天恰好完成；若赵师傅先做5天、王师傅再做17天也恰好完成。两人合作，需要多少天完成？","options":["22","11","12","13"],"answer":1,"explanation":"设王师傅每天完成x、赵师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=22÷2=11天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40315","module":"shuliang","prompt":"某商品进价800元，售价1064元。该商品的利润率是多少？","options":["27%","40%","33%","66%"],"answer":2,"explanation":"利润=1064−800=264元，利润率=264÷800×100%=33%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40316","module":"shuliang","prompt":"六名同学排成一排合影，其中甲、乙两人约定不相邻，共有多少种不同的排法？","options":["240","720","480","600"],"answer":2,"explanation":"六人全排列共6!=720种；甲、乙相邻的排法为2×5!=240种；故不相邻共720−240=480种。","exam":"通用基础","__sub":"排列组合","diff":3},{"id":"sl-40317","module":"shuliang","prompt":"7名选手排成一排合影留念，其中甲、乙两人必须相邻，共有多少种不同的排法？","options":["1440","5040","720","2880"],"answer":0,"explanation":"把甲、乙捆绑成一个整体，与其余5人共6个元素全排列，有(6)!=720种；甲、乙内部可交换有2种；共2×720=1440种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40318","module":"shuliang","prompt":"一个长方形的长为21米，宽为16米，它的周长是多少米？","options":["336","74","37","76"],"answer":1,"explanation":"长方形周长=2×（长+宽）=2×(21+16)=74米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40319","module":"shuliang","prompt":"两个正数的和为38，要使它们的乘积最大，则最大的乘积是多少？","options":["361","38","366","358"],"answer":0,"explanation":"两数和一定时，两数相等时乘积最大，均为38÷2=19，最大乘积=19×19=361。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40320","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才16岁。”乙对甲说：“当我到你这么大时，你就61岁了。”甲今年多少岁？","options":["31","46","47","45"],"answer":1,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙16岁，即乙现在为x+d；乙到甲现在这么大时甲61岁，即甲现在为y−d。由y−d−(x+d)=d得d=(61−16)÷3=15，甲今年=61−15=46岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40321","module":"shuliang","prompt":"把90个名额按8:5:5的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["50","25","65","40"],"answer":3,"explanation":"总份数=8+5+5=18，每份90÷18=5个，最多的班级分得8×5=40个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40322","module":"shuliang","prompt":"袋中有2个红球和4个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["2/3","1/3","1","1/2"],"answer":1,"explanation":"共有6个球，红球2个，取到红球的概率为2/6=1/3。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40323","module":"shuliang","prompt":"今天是星期二，再过160天是星期几？","options":["星期日","星期二","星期一","星期三"],"answer":2,"explanation":"160÷7=22余6，星期二往后推6天是星期一。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40324","module":"shuliang","prompt":"已知等差数列的首项为7，公差为4，则它的前11项之和是多少？","options":["295","517","303","297"],"answer":3,"explanation":"第11项=7+(11-1)×4=47，前11项和=n×(首项+末项)÷2=11×(7+47)÷2=297。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40325","module":"shuliang","prompt":"袋中有4个红球和7个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["7/11","4/11","1","1/2"],"answer":1,"explanation":"共有11个球，红球4个，取到红球的概率为4/11。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40326","module":"shuliang","prompt":"6个正整数之和为76（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["13","15","11","12"],"answer":0,"explanation":"最大数最小时各数尽量平均，76÷6=12余4，故最大数至少为13（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40327","module":"shuliang","prompt":"某商品按进价加价50%定价，然后按7折出售，仍可获利。该商品的利润率是多少？","options":["12%","35%","5%","14%"],"answer":2,"explanation":"设进价为100，售价=100×(1+50%)×7/10=105，利润率=105−100=5%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40328","module":"shuliang","prompt":"某小组共有11名成员，现从中随机选出3名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["84","165","81","82"],"answer":2,"explanation":"从11人中选3人共C(11,3)=165种；甲、乙都不入选有C(9,3)=84种；故至少一人入选共165−84=81种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40329","module":"shuliang","prompt":"甲种卡车每次可运8吨货物，耗油12升；乙种卡车每次可运2吨货物，耗油6升。现要运送64吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["192","104","92","96"],"answer":3,"explanation":"甲车每吨耗油12/8升，乙车每吨耗油6/2升，甲车更省。尽量用甲车：8车次运64吨，余0吨用乙车0次，共耗油96升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40330","module":"shuliang","prompt":"A接水需要5分钟，B接水需要9分钟，C接水需要10分钟，D接水需要6分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["30","72","60","36"],"answer":3,"explanation":"让用时短的人先接水可使总等待时间最短。按5、6、9、10的顺序，总等待=5×3+6×2+9×1+10×0=36分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40331","module":"shuliang","prompt":"今年甲的年龄是乙的5倍，10年后甲的年龄是乙的4倍。乙今年多少岁？","options":["33","30","28","10"],"answer":1,"explanation":"设乙今年x岁，则甲为5x岁；10年后：5x+10=4(x+10)，解得x=30岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40332","module":"shuliang","prompt":"同时掷两枚均匀的骰子，点数之和为7的概率是多少？","options":["1/6","5/36","7/36","1/12"],"answer":0,"explanation":"两枚骰子共6×6=36种等可能结果，点数之和为7的有6种，概率为6/36=1/6。","exam":"通用基础","__sub":"概率问题","diff":2},{"id":"sl-40333","module":"shuliang","prompt":"已知等差数列的前10项和为210，前20项和为820，则该数列的公差是多少？","options":["3","5","4","1"],"answer":2,"explanation":"S20−2×S10=(820)−2×(210)=400=100d（第11到20项之和比前10项之和多100d），故d=4。","exam":"通用基础","__sub":"数列问题","diff":3}]);